-- Queer Atlas: verified queer and queer-friendly electronic events, Batch 6.
-- Countries: Estonia, Latvia, Lithuania and Hungary. Researched 2026-08-29.
-- Unpublished venue or timing details remain explicit instead of being inferred.
-- Source data contains no vibe_tags; UPDATE and INSERT force ARRAY[]::text[].

begin;

alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;

with src as (
  select * from jsonb_to_recordset($qa_baltic_hungary_batch6_events$
[
{"name":"Is This What You Wanted? – Tallinn Fringe 2026","aliases":["IS THIS WHAT YOU WANTED?","happeningfish Tallinn Fringe 2026"],"city":"tallinn","date":"2026-09-04","start_date":"2026-09-04","end_date":"2026-09-05","description":"Trans comedian happeningfish performs two English-language Tallinn Fringe shows combining filthy stand-up, emotional labour, queer politics and laughter as activism.","link":"https://fringe.ee/tickets/is-this-what-you-wanted-190048/","ticket_url":"https://fringe.ee/tickets/is-this-what-you-wanted-190048/","location":"Heldeke!, Telliskivi 62, 10412 Tallinn, Estonia","lat":59.4394,"lng":24.7286,"vibe":"smart trans stand-up balancing vulnerable storytelling, queer politics and gloriously dirty jokes","intel":{"entry_wait":"Two one-hour performances are listed for 4 and 5 September; choose the correct date when booking and arrive before the 21:00 start.","best_arrival":"Reach Heldeke! around 20:30 for ticket check and seating because the intimate performance room has limited capacity.","crowd_mix":"Queer and trans audiences, English-speaking locals, Fringe visitors, comedy followers and international cultural travellers attend.","dress_code":"No appearance requirement applies; comfortable theatre or bar clothing is appropriate for the compact underground room.","host_inclusivity":"The trans performer's work explicitly examines queer politics, transgender experience, activism, allyship and survival through comedy.","source_urls":["https://fringe.ee/tickets/is-this-what-you-wanted-190048/"],"research_status":"official_festival_dates_times_venue_age_language_and_queer_content_verified","updated_at":"2026-08-29T00:00:00Z"}},
